#!/bin/bash
# DEPLOY_v2_close — فحص موجّه ← Smoke ← Full Gate، بالتسلسل وفي لصقة واحدة.
# Full Gate لا تبدأ إلا إذا نجح Smoke، فلا تُهدر 40 دقيقة بلا داعٍ.
# لا تفعيل إنتاج، ولا مساس بـapp.py.   الاستعمال:  bash DEPLOY_v2_close.sh
set -u
cd /opt/LegalMind || exit 1
cat > /tmp/v2close.b64 <<'B64EOF'

B64EOF
base64 -d /tmp/v2close.b64 > /tmp/v2close.tgz || { echo "B64_FAIL"; exit 1; }
[ -f mcp/server.py ] && cp mcp/server.py "mcp/server.py.bak_$(date +%s)"
tar xzf /tmp/v2close.tgz -C /opt/LegalMind || { echo "UNTAR_FAIL"; exit 1; }
set -a; . /opt/LegalMind/deploy/.env; set +a
nohup /opt/LegalMind/admin/.venv/bin/python \
      /opt/LegalMind/tools/v2_close.py > /tmp/v2close.log 2>&1 &
disown
echo "بدأ. تابع:  tail -f /tmp/v2close.log"
echo "الفحص الموجّه + Smoke ~10 دقائق؛ فإن نجح تبدأ Full Gate تلقائيًا (~40 دقيقة)."
